// Pixel load event listener
jQuery(document).on("pmw:load-pixels", () => {

	if (
		wpmDataLayer?.pixels?.adroll?.advertiser_id
		&& wpmDataLayer?.pixels?.adroll?.pixel_id
		&& !wpmDataLayer?.pixels?.adroll?.loaded) {
		if (wpm.consent.canPixelBeFired("marketing", "Adroll")) wpm.load_adroll_pixel()
	}
})

// view search event
// https://gist.github.com/dennismarlowe/c6826c360d34d9cf5ba7f7011e8a9741#file-product-search
jQuery(document).on("pmw:browser:search", (event, payload) => {

	try {
		if (wpm.canNotFireAdrollEvent()) return

		const adrollData = payload.pixels?.adroll;
		if (!adrollData) return;

		window.adroll.track(adrollData.event_name, adrollData.event_data)
		pmw.console.log("Adroll: productSearch event sent", adrollData.event_data)

	} catch (e) {
		console.error(e)
	}
})

